package com.gabriel.springrestspecialist.domain.repository;import com.gabriel.springrestspecialist.domain.model.Restaurant;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.stereotype.Repository;import java.math.BigDecimal;import java.util.List;import java.util.Optional;import java.util.UUID;@Repositorypublic interface RestaurantRepository extends JpaRepository<Restaurant, UUID> {    @Query("FROM Restaurant r JOIN FETCH r.cuisine")    List<Restaurant> findAll();    @Query("FROM Restaurant r JOIN FETCH r.cuisine WHERE r.name LIKE %:name%")    Optional<List<Restaurant>> findByNameContaining(String name);    @Query(value = "FROM Restaurant r JOIN FETCH r.cuisine WHERE r.deliveryFee BETWEEN :min AND :max")    Optional<List<Restaurant>> findByDeliveryFeeBetween(BigDecimal min, BigDecimal max);    Optional<List<Restaurant>> findAllFreeDelivery();}